def calc(expr: str) -> int | str:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in '+-*/%^()':
            tokens.append(c)
            i += 1
        else:
            i += 1

    pos = 0

    def parse_expr():
        val = parse_term()
        nonlocal pos
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                val = val + right
            else:
                val = val - right
        return val

    def parse_term():
        val = parse_unary()
        nonlocal pos
        while pos < len(tokens) and tokens[pos] in ('*', '/', '%'):
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == '*':
                val = val * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError
                val = int(val / right)
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError
                q = int(val / right)
                val = val - right * q
        return val

    def parse_unary():
        nonlocal pos
        count = 0
        while pos < len(tokens) and tokens[pos] == '-':
            count += 1
            pos += 1
        val = parse_power()
        if count % 2 == 1:
            val = -val
        return val

    def parse_power():
        nonlocal pos
        base = parse_primary()
        if pos < len(tokens) and tokens[pos] == '^':
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative power")
            return pow(base, exp)
        return base

    def parse_primary():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        if isinstance(token, int):
            return token
        elif token == '(':
            val = parse_expr()
            pos += 1  # consume ')'
            return val
        else:
            raise ValueError(f"Unexpected token {token}")

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
